const escapeHTML = value => String(value ?? '').replace(/[&<>"']/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const params=new URLSearchParams(location.search);
let property=null, photoIndex=0;
const gallery=document.getElementById('gallery-dialog');
function showPhoto(index){if(!property)return;photoIndex=(index+property.photos.length)%property.photos.length;const img=gallery.querySelector('.gallery-main');img.src=property.photos[photoIndex];img.alt=`${property.nazev} — fotografie ${photoIndex+1}`;gallery.querySelector('.gallery-counter').textContent=`${photoIndex+1} / ${property.photos.length}`;gallery.querySelectorAll('[data-photo]').forEach((b,i)=>b.classList.toggle('active',i===photoIndex));}
function openGallery(index=0){showPhoto(index);gallery.showModal();}
fetch('data/nemovitosti.json').then(r=>{if(!r.ok)throw Error('data');return r.json();}).then(listings=>{
  property=listings.find(d=>d.id===params.get('id'));
  if(!property){document.getElementById('property-content').innerHTML='<div class="container empty-state"><p class="eyebrow">NEMOVITOST NENALEZENA</p><h1>Tuhle nabídku se nepodařilo najít</h1><p>Podívejte se na ostatní nemovitosti nebo mi zavolejte.</p><a class="button button-dark" href="index.html#nemovitosti">Zpět na nabídku <svg class="icon" aria-hidden="true" focusable="false"><use href="assets/icons.svg#arrow-right"></use></svg></a></div>';return;}
  const d=property;
  document.title=`${d.nazev} | Jiří Mayrich`;
  document.querySelector('meta[name="description"]').content=`${d.nazev}. ${d.cena_text}. Fotografie, podrobnosti a osobní prohlídka s Jiřím Mayrichem.`;
  const type=d.type==='byty'?`Byt ${d.params.Subtyp?.replace('bytu ','')||''}`:d.type==='chaty'?'Chata':d.type==='pozemky'?'Stavební pozemek':'Rodinný dům';
  const area=d.params['Plocha užitná']||d.params['Celková plocha']||'';
  const description=d.popis_markdown.split(/\n\s*\n/).map(p=>`<p>${escapeHTML(p.trim()).replace(/\n/g,'<br>')}</p>`).join('');
  const video=d.videa.find(v=>v.typ==='youtube');
  const visualization=['123376','111961'].includes(d.id);
  document.getElementById('property-content').innerHTML=`<div class="container"><nav class="breadcrumbs" aria-label="Drobečková navigace"><a href="index.html">Úvod</a><span>/</span><a href="index.html#nemovitosti">Nemovitosti</a><span>/</span><span>${escapeHTML(d.city)}</span></nav><div class="detail-heading"><div><p class="eyebrow">NA PRODEJ · ${escapeHTML(d.city.toUpperCase())}</p><h1>${escapeHTML(type)} <em>${escapeHTML(area)}</em></h1><p>${escapeHTML([d.params.Ulice,d.city].filter(Boolean).join(', '))}</p></div><div class="detail-price"><span>${escapeHTML(d.cena_text)}</span><small>${escapeHTML(d.stav_prodeje)}</small></div></div><div class="detail-photos"><button data-open-photo="0" class="detail-cover" aria-label="Otevřít všechny fotografie"><img src="${d.photos[0]}" alt="${escapeHTML(d.nazev)}" fetchpriority="high">${visualization?'<span class="visualization-badge">VIZUALIZACE</span>':''}<span class="photo-label">Prohlédnout ${d.photos.length} fotografií <svg class="icon" aria-hidden="true" focusable="false"><use href="assets/icons.svg#arrow-right"></use></svg></span></button><button data-open-photo="1" aria-label="Zobrazit fotografii 2"><img src="${d.photos[1]||d.photos[0]}" alt="${escapeHTML(d.nazev)} — fotografie 2"></button><button data-open-photo="2" aria-label="Zobrazit fotografii 3"><img src="${d.photos[2]||d.photos[0]}" alt="${escapeHTML(d.nazev)} — fotografie 3"></button></div><div class="detail-layout"><div class="detail-description"><div class="detail-facts"><div><small>UŽITNÁ PLOCHA</small><strong>${escapeHTML(d.params['Plocha užitná']||area)}</strong></div><div><small>STAV NEMOVITOSTI</small><strong>${escapeHTML(d.params['Stav nemovitosti']||'Dle popisu')}</strong></div><div><small>ENERGETICKÁ TŘÍDA</small><strong>${escapeHTML(d.params['Energetická třída']?.split(' - ')[0]||'Neuvedeno')}</strong></div></div><p class="eyebrow">O NEMOVITOSTI</p><h2>${escapeHTML(d.nazev)}</h2><div class="property-description-copy">${description}</div><h2 class="parameters-heading">Vše důležité na jednom místě</h2><dl class="parameters">${d.parametry.map(p=>`<div><dt>${escapeHTML(p.nazev)}</dt><dd>${escapeHTML(p.hodnota)}</dd></div>`).join('')}</dl>${video?`<div class="detail-video"><p class="eyebrow">PROJDĚTE SE SE MNOU</p><h2>Videoprohlídka</h2><div id="property-video"><button id="load-video" class="button button-dark">Přehrát videoprohlídku na YouTube <svg class="icon" aria-hidden="true" focusable="false"><use href="assets/icons.svg#play"></use></svg></button><p class="video-privacy">Kliknutím načtete video ze služby YouTube.</p></div></div>`:''}<p class="detail-source">Údaje převzaty z nabídky ze dne 23. 9. 2026. Aktuální dostupnost vám rád potvrdím.</p></div><aside class="agent-card"><img src="assets/jiri-mayrich.webp" alt="Jiří Mayrich" width="130" height="130"><p class="eyebrow">VAŠÍM PRŮVODCEM BUDE</p><h2>Jiří Mayrich</h2><p class="agent-qualification">Certifikovaný realitní makléř<br>a lektor RVI</p><p>Rád vám nemovitost ukážu<br>a odpovím na vaše otázky.</p><a class="button button-gold" href="index.html?intent=koupe&nemovitost=${d.id}#kontakt">Domluvit prohlídku <svg class="icon" aria-hidden="true" focusable="false"><use href="assets/icons.svg#arrow-right"></use></svg></a><a class="agent-phone" href="tel:+420721889434"><svg class="icon" aria-hidden="true" focusable="false"><use href="assets/icons.svg#phone"></use></svg> +420 721 889 434</a><a class="agent-email" href="mailto:jmayrich@jaros-partners.cz?subject=${encodeURIComponent('Zájem o nemovitost: '+d.nazev)}">jmayrich@jaros-partners.cz</a><span class="agent-footnote">OSOBNĚ. OD PRVNÍ PROHLÍDKY.</span></aside></div><div class="detail-back"><a class="button button-outline" href="index.html#nemovitosti"><svg class="icon" aria-hidden="true" focusable="false"><use href="assets/icons.svg#arrow-left"></use></svg> Zpět na všechny nemovitosti</a></div></div>`;
  gallery.querySelector('.gallery-thumbs').innerHTML=d.photos.map((src,i)=>`<button data-photo="${i}" aria-label="Fotografie ${i+1}"><img src="${src}" alt="" loading="lazy"></button>`).join('');
  document.querySelectorAll('[data-open-photo]').forEach(b=>b.addEventListener('click',()=>openGallery(Number(b.dataset.openPhoto))));
  gallery.querySelectorAll('[data-photo]').forEach(b=>b.addEventListener('click',()=>showPhoto(Number(b.dataset.photo))));
  document.getElementById('load-video')?.addEventListener('click',()=>{const iframe=document.createElement('iframe');iframe.src=video.url.replace('www.youtube.com','www.youtube-nocookie.com');iframe.title='Videoprohlídka: '+d.nazev;iframe.allow='autoplay; encrypted-media; picture-in-picture';iframe.allowFullscreen=true;document.getElementById('property-video').replaceChildren(iframe);});
}).catch(()=>{document.getElementById('property-content').innerHTML='<div class="container empty-state"><h1>Nabídku se nepodařilo načíst</h1><p>Zkuste stránku obnovit, nebo mi zavolejte na <a href="tel:+420721889434">+420 721 889 434</a>.</p><a class="button button-dark" href="index.html#nemovitosti">Zpět na nabídku</a></div>';});
gallery.querySelector('.dialog-close').addEventListener('click',()=>gallery.close());
gallery.querySelector('.gallery-prev').addEventListener('click',()=>showPhoto(photoIndex-1));
gallery.querySelector('.gallery-next').addEventListener('click',()=>showPhoto(photoIndex+1));
document.addEventListener('keydown',e=>{if(gallery.open&&e.key==='ArrowLeft'){e.preventDefault();showPhoto(photoIndex-1);}if(gallery.open&&e.key==='ArrowRight'){e.preventDefault();showPhoto(photoIndex+1);}});
